$$//.cs  文件类型，便于外部编辑时使用
// 引用必要的命名空间
using System.Runtime.InteropServices;

// Quicker将会调用的函数
public static string Exec(string paramValue)
{
   dynamic app = Marshal.GetActiveObject("{progId}");
    
    app.ActiveWindow.FreezePanes = !app.ActiveWindow.FreezePanes;
    
    Marshal.ReleaseComObject(app);
    return "ok";
}
